import { RefObject } from 'react';

/**
 * Determines if toolbar fits well in bounds, depending on the available space of the container
 *
 * @param toolbarWidth -
 * @param boundariesRef -
 */
export function doesFitInBounds(
  toolbarWidth: number,
  boundariesRef: RefObject<HTMLDivElement>,
): boolean {
  const { clientWidth: boundaryWidth } = boundariesRef.current ?? {
    clientWidth: 0,
  };

  return toolbarWidth < boundaryWidth / 2;
}
